*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-bg:        #fafaf9;
  --clr-surface:   #ffffff;
  --clr-border:    #e8e5e0;
  --clr-text:      #1a1a18;
  --clr-muted:     #6b6860;
  --clr-accent:    #c9a96e;
  --clr-accent-dk: #a8833d;
  --clr-red:       #d94f3d;
  --clr-green:     #2e7d5a;
  --radius-sm:     6px;
  --radius-md:     12px;
  --radius-lg:     20px;
  --shadow-sm:     0 1px 4px rgba(0,0,0,.06);
  --shadow-md:     0 4px 18px rgba(0,0,0,.10);
  --shadow-lg:     0 12px 40px rgba(0,0,0,.14);
  --transition:    .22s cubic-bezier(.4,0,.2,1);
  --max-w:         1280px;
  --font-sans:     'Inter', system-ui, sans-serif;
  --font-serif:    'Playfair Display', Georgia, serif;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--clr-bg);
  color: var(--clr-text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; }
a  { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font: inherit; }

/* ─── Layout helpers ───────────────────────────────────────────────────────── */
.container { max-width: var(--max-w); margin-inline: auto; padding-inline: 24px; }

/* ─── TOP BAR ──────────────────────────────────────────────────────────────── */
.top-bar {
  background: var(--clr-text);
  color: #fff;
  text-align: center;
  font-size: .78rem;
  letter-spacing: .06em;
  padding: 9px 16px;
  position: relative;
}
.top-bar .close-bar {
  position: absolute; right: 16px; top: 50%; transform: translateY(-50%);
  color: rgba(255,255,255,.6);
  font-size: 1rem; line-height: 1;
  transition: color var(--transition);
}
.top-bar .close-bar:hover { color: #fff; }

/* ─── HEADER ───────────────────────────────────────────────────────────────── */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: var(--clr-surface);
  border-bottom: 1px solid var(--clr-border);
  backdrop-filter: blur(8px);
}
.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 16px;
  height: 68px;
}
.logo {
  font-family: var(--font-serif);
  font-size: 1.55rem;
  font-weight: 700;
  letter-spacing: -.01em;
  color: var(--clr-text);
}
.logo span { color: var(--clr-accent); }

.main-nav { display: flex; gap: 0; list-style: none; justify-content: center; }
.main-nav a {
  font-size: .85rem;
  font-weight: 500;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: 8px 14px;
  color: var(--clr-muted);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.main-nav a:hover, .main-nav a.active { color: var(--clr-text); background: var(--clr-bg); }

.header-actions { display: flex; align-items: center; justify-content: flex-end; gap: 6px; }
.icon-btn {
  display: flex; align-items: center; justify-content: center;
  width: 40px; height: 40px; border-radius: 50%;
  color: var(--clr-muted);
  transition: background var(--transition), color var(--transition);
  position: relative;
}
.icon-btn:hover { background: var(--clr-bg); color: var(--clr-text); }
.icon-btn svg { width: 20px; height: 20px; }
.cart-badge {
  position: absolute; top: 4px; right: 4px;
  width: 16px; height: 16px; border-radius: 50%;
  background: var(--clr-red);
  color: #fff; font-size: .6rem; font-weight: 700;
  display: flex; align-items: center; justify-content: center;
}

/* ─── HERO ─────────────────────────────────────────────────────────────────── */
.hero {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 580px;
  overflow: hidden;
}
.hero-content {
  display: flex; flex-direction: column; justify-content: center;
  padding: 64px 56px;
  background: #f3ede4;
}
.hero-eyebrow {
  font-size: .72rem; font-weight: 600; letter-spacing: .18em;
  text-transform: uppercase; color: var(--clr-accent-dk);
  margin-bottom: 18px;
}
.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.4rem, 4vw, 3.4rem);
  line-height: 1.15;
  font-weight: 700;
  margin-bottom: 20px;
}
.hero-title em { font-style: normal; color: var(--clr-accent-dk); }
.hero-sub { font-size: 1.05rem; color: var(--clr-muted); max-width: 38ch; margin-bottom: 36px; }
.hero-ctas { display: flex; gap: 12px; flex-wrap: wrap; }

.hero-visual {
  position: relative; overflow: hidden;
  background: linear-gradient(135deg, #d9ccbf 0%, #c4b49e 100%);
}
.hero-visual img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform .8s ease;
}
.hero-visual:hover img { transform: scale(1.04); }
.hero-badge {
  position: absolute; bottom: 32px; left: 32px;
  background: var(--clr-surface); border-radius: var(--radius-md);
  padding: 14px 18px;
  box-shadow: var(--shadow-md);
  display: flex; align-items: center; gap: 12px;
}
.hero-badge-icon { font-size: 1.8rem; }
.hero-badge-text strong { display: block; font-size: .9rem; }
.hero-badge-text span { font-size: .78rem; color: var(--clr-muted); }

/* ─── BUTTONS ──────────────────────────────────────────────────────────────── */
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 13px 28px; border-radius: var(--radius-sm);
  font-size: .88rem; font-weight: 600; letter-spacing: .02em;
  transition: background var(--transition), color var(--transition),
              transform var(--transition), box-shadow var(--transition);
}
.btn:active { transform: translateY(1px); }

.btn-primary {
  background: var(--clr-text); color: #fff;
  box-shadow: 0 2px 8px rgba(0,0,0,.18);
}
.btn-primary:hover { background: #333330; box-shadow: var(--shadow-md); }

.btn-outline {
  background: transparent; color: var(--clr-text);
  border: 2px solid var(--clr-text);
}
.btn-outline:hover { background: var(--clr-text); color: #fff; }

.btn-accent {
  background: var(--clr-accent); color: #fff;
  box-shadow: 0 2px 8px rgba(201,169,110,.35);
}
.btn-accent:hover { background: var(--clr-accent-dk); }

.btn-ghost {
  background: transparent; color: var(--clr-muted);
  padding-inline: 0;
}
.btn-ghost:hover { color: var(--clr-text); }
.btn-ghost .arrow { transition: transform var(--transition); }
.btn-ghost:hover .arrow { transform: translateX(4px); }

/* ─── SECTION HEADERS ──────────────────────────────────────────────────────── */
.section-header {
  display: flex; align-items: flex-end; justify-content: space-between;
  margin-bottom: 32px; gap: 16px;
}
.section-label {
  font-size: .72rem; font-weight: 600; letter-spacing: .18em;
  text-transform: uppercase; color: var(--clr-accent-dk);
  margin-bottom: 8px;
}
.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 2.5vw, 2rem);
  font-weight: 700; line-height: 1.2;
}
.section-sub { font-size: .9rem; color: var(--clr-muted); margin-top: 6px; }

/* ─── CATEGORY STRIP ───────────────────────────────────────────────────────── */
.categories { padding: 48px 0; }
.cat-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.cat-card {
  position: relative; border-radius: var(--radius-md);
  overflow: hidden; cursor: pointer;
  aspect-ratio: 3/4;
  background: var(--clr-border);
  transition: transform var(--transition), box-shadow var(--transition);
}
.cat-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.cat-card img { width: 100%; height: 100%; object-fit: cover; transition: transform .5s ease; }
.cat-card:hover img { transform: scale(1.06); }
.cat-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.55) 0%, transparent 55%);
  display: flex; align-items: flex-end; padding: 18px;
}
.cat-name { color: #fff; font-weight: 600; font-size: .9rem; letter-spacing: .02em; }

/* ─── FEATURED PRODUCTS ────────────────────────────────────────────────────── */
.featured { padding: 64px 0; background: var(--clr-surface); }
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.product-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--clr-bg);
  border: 1px solid var(--clr-border);
  transition: transform var(--transition), box-shadow var(--transition);
  display: flex; flex-direction: column;
}
.product-card:hover { transform: translateY(-6px); box-shadow: var(--shadow-lg); }

.product-image-wrap {
  position: relative;
  aspect-ratio: 1 / 1.1;
  overflow: hidden;
  background: #f0ebe3;
}
.product-image-wrap img { width: 100%; height: 100%; object-fit: cover; transition: transform .5s ease; }
.product-card:hover .product-image-wrap img { transform: scale(1.07); }

.product-badges {
  position: absolute; top: 12px; left: 12px;
  display: flex; flex-direction: column; gap: 6px;
}
.badge {
  display: inline-block; padding: 3px 9px;
  border-radius: 99px; font-size: .68rem; font-weight: 700;
  letter-spacing: .06em; text-transform: uppercase;
}
.badge-new   { background: var(--clr-text);  color: #fff; }
.badge-sale  { background: var(--clr-red);   color: #fff; }
.badge-hot   { background: var(--clr-accent); color: #fff; }
.badge-eco   { background: var(--clr-green); color: #fff; }

.product-wishlist {
  position: absolute; top: 12px; right: 12px;
  width: 34px; height: 34px; border-radius: 50%;
  background: rgba(255,255,255,.85); backdrop-filter: blur(4px);
  display: flex; align-items: center; justify-content: center;
  color: var(--clr-muted); font-size: 1rem;
  opacity: 0; transform: translateY(-4px);
  transition: opacity var(--transition), transform var(--transition), color var(--transition);
}
.product-card:hover .product-wishlist { opacity: 1; transform: translateY(0); }
.product-wishlist:hover { color: var(--clr-red); }

.product-quick-add {
  position: absolute; bottom: 0; left: 0; right: 0;
  background: rgba(26,26,24,.88); backdrop-filter: blur(4px);
  color: #fff; font-size: .8rem; font-weight: 600; letter-spacing: .04em;
  padding: 12px; text-align: center;
  opacity: 0; transform: translateY(100%);
  transition: opacity var(--transition), transform var(--transition);
}
.product-card:hover .product-quick-add { opacity: 1; transform: translateY(0); }

.product-info { padding: 16px; flex: 1; display: flex; flex-direction: column; }
.product-brand {
  font-size: .72rem; font-weight: 600; letter-spacing: .1em;
  text-transform: uppercase; color: var(--clr-muted); margin-bottom: 5px;
}
.product-name {
  font-size: .95rem; font-weight: 600; line-height: 1.35;
  margin-bottom: 10px; flex: 1;
}
.product-rating { display: flex; align-items: center; gap: 6px; margin-bottom: 10px; }
.stars { color: var(--clr-accent); font-size: .78rem; letter-spacing: .02em; }
.rating-count { font-size: .75rem; color: var(--clr-muted); }
.product-price { display: flex; align-items: center; gap: 8px; }
.price-current { font-size: 1.05rem; font-weight: 700; }
.price-original { font-size: .88rem; color: var(--clr-muted); text-decoration: line-through; }
.price-save { font-size: .75rem; font-weight: 600; color: var(--clr-red); }

/* ─── DEALS BANNER ─────────────────────────────────────────────────────────── */
.deals { padding: 64px 0; }
.deals-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}
.deal-card {
  border-radius: var(--radius-lg);
  overflow: hidden; position: relative;
  min-height: 300px;
  display: flex; align-items: center;
}
.deal-card img {
  position: absolute; inset: 0;
  width: 100%; height: 100%; object-fit: cover;
}
.deal-card-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(120deg, rgba(0,0,0,.65) 0%, transparent 70%);
}
.deal-card-content {
  position: relative; z-index: 1;
  padding: 40px 44px; color: #fff;
}
.deal-tag {
  display: inline-block; background: var(--clr-red);
  padding: 4px 12px; border-radius: 99px;
  font-size: .72rem; font-weight: 700; letter-spacing: .1em;
  text-transform: uppercase; margin-bottom: 14px;
}
.deal-title {
  font-family: var(--font-serif);
  font-size: clamp(1.3rem, 2.5vw, 1.9rem);
  font-weight: 700; line-height: 1.2;
  margin-bottom: 10px;
}
.deal-sub { font-size: .88rem; opacity: .85; margin-bottom: 24px; }

.deal-countdown { display: flex; gap: 10px; margin-bottom: 24px; }
.countdown-unit {
  background: rgba(255,255,255,.18); backdrop-filter: blur(6px);
  border: 1px solid rgba(255,255,255,.3);
  border-radius: var(--radius-sm);
  padding: 8px 14px; text-align: center; min-width: 56px;
}
.countdown-unit strong { display: block; font-size: 1.4rem; font-weight: 700; line-height: 1; }
.countdown-unit span  { font-size: .65rem; letter-spacing: .08em; text-transform: uppercase; opacity: .75; }

.deal-card.deal-secondary .deal-card-overlay {
  background: linear-gradient(to bottom, rgba(0,0,0,.1) 0%, rgba(0,0,0,.6) 100%);
}
.deal-card.deal-secondary .deal-card-content {
  position: absolute; bottom: 0; left: 0; right: 0;
}

/* ─── EDITORIAL ────────────────────────────────────────────────────────────── */
.editorial { padding: 64px 0; background: var(--clr-surface); }
.editorial-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  gap: 24px;
  align-items: start;
}
.article-card { border-radius: var(--radius-md); overflow: hidden; cursor: pointer; }
.article-card:hover .article-image img { transform: scale(1.05); }
.article-image { overflow: hidden; aspect-ratio: 4/3; background: var(--clr-border); }
.article-card.featured-article .article-image { aspect-ratio: 16/11; }
.article-image img { width: 100%; height: 100%; object-fit: cover; transition: transform .5s ease; }
.article-body { padding: 20px 0 0; }
.article-category {
  font-size: .7rem; font-weight: 700; letter-spacing: .14em;
  text-transform: uppercase; color: var(--clr-accent-dk); margin-bottom: 8px;
}
.article-title {
  font-family: var(--font-serif);
  font-size: 1.15rem; font-weight: 700; line-height: 1.35;
  margin-bottom: 8px;
  transition: color var(--transition);
}
.article-card:hover .article-title { color: var(--clr-accent-dk); }
.article-card.featured-article .article-title { font-size: 1.45rem; }
.article-excerpt { font-size: .87rem; color: var(--clr-muted); line-height: 1.65; margin-bottom: 14px; }
.article-meta { font-size: .75rem; color: var(--clr-muted); display: flex; gap: 12px; }
.article-meta span::before { content: '·'; margin-right: 12px; }
.article-meta span:first-child::before { content: ''; margin: 0; }

/* ─── BRAND STRIP ──────────────────────────────────────────────────────────── */
.brands { padding: 48px 0; border-block: 1px solid var(--clr-border); }
.brands-inner { display: flex; align-items: center; gap: 0; overflow: hidden; }
.brands-track {
  display: flex; align-items: center; gap: 64px;
  animation: scroll-brands 22s linear infinite;
  white-space: nowrap; min-width: max-content;
}
.brands-track:hover { animation-play-state: paused; }
@keyframes scroll-brands {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}
.brand-logo {
  font-family: var(--font-serif);
  font-size: 1.1rem; font-weight: 700; letter-spacing: .06em;
  color: var(--clr-border);
  text-transform: uppercase;
  transition: color var(--transition);
  user-select: none;
}
.brand-logo:hover { color: var(--clr-muted); }

/* ─── NEWSLETTER ───────────────────────────────────────────────────────────── */
.newsletter {
  padding: 80px 0;
  background: var(--clr-text);
  color: #fff;
  text-align: center;
}
.newsletter .section-label { color: var(--clr-accent); }
.newsletter .section-title { color: #fff; margin-bottom: 12px; }
.newsletter-sub { color: rgba(255,255,255,.6); font-size: .95rem; margin-bottom: 36px; }
.newsletter-form {
  display: flex; max-width: 460px; margin-inline: auto;
  border: 1px solid rgba(255,255,255,.2); border-radius: var(--radius-sm);
  overflow: hidden;
  background: rgba(255,255,255,.06);
}
.newsletter-form input {
  flex: 1; background: transparent; border: none; outline: none;
  padding: 14px 18px; color: #fff; font: inherit; font-size: .9rem;
}
.newsletter-form input::placeholder { color: rgba(255,255,255,.4); }
.newsletter-form .btn { border-radius: 0; padding-block: 14px; }
.newsletter-note { font-size: .76rem; color: rgba(255,255,255,.35); margin-top: 14px; }

/* ─── FOOTER ───────────────────────────────────────────────────────────────── */
.site-footer {
  background: #111110; color: rgba(255,255,255,.7);
  padding-top: 64px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px; padding-bottom: 56px;
  border-bottom: 1px solid rgba(255,255,255,.08);
}
.footer-brand .logo { color: #fff; margin-bottom: 14px; }
.footer-brand p { font-size: .87rem; line-height: 1.7; max-width: 30ch; margin-bottom: 20px; }
.footer-social { display: flex; gap: 10px; }
.social-btn {
  width: 36px; height: 36px; border-radius: 50%;
  border: 1px solid rgba(255,255,255,.15);
  display: flex; align-items: center; justify-content: center;
  font-size: .85rem; color: rgba(255,255,255,.5);
  transition: border-color var(--transition), color var(--transition), background var(--transition);
}
.social-btn:hover { border-color: var(--clr-accent); color: var(--clr-accent); background: rgba(201,169,110,.08); }

.footer-col h4 {
  font-size: .78rem; font-weight: 700; letter-spacing: .12em;
  text-transform: uppercase; color: #fff; margin-bottom: 18px;
}
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-col ul a { font-size: .87rem; color: rgba(255,255,255,.5); transition: color var(--transition); }
.footer-col ul a:hover { color: #fff; }

.footer-bottom {
  display: flex; align-items: center; justify-content: space-between;
  padding-block: 22px; font-size: .8rem;
  flex-wrap: wrap; gap: 12px;
}
.footer-bottom-links { display: flex; gap: 24px; }
.footer-bottom-links a { color: rgba(255,255,255,.35); transition: color var(--transition); }
.footer-bottom-links a:hover { color: rgba(255,255,255,.7); }
.footer-payments { display: flex; gap: 8px; }
.pay-chip {
  background: rgba(255,255,255,.08);
  border-radius: 4px; padding: 4px 10px;
  font-size: .72rem; font-weight: 600; color: rgba(255,255,255,.5);
  letter-spacing: .04em;
}

/* ─── TOAST ────────────────────────────────────────────────────────────────── */
.toast-container {
  position: fixed; bottom: 24px; right: 24px;
  display: flex; flex-direction: column; gap: 10px;
  z-index: 9999;
}
.toast {
  background: var(--clr-text); color: #fff;
  padding: 14px 20px; border-radius: var(--radius-md);
  font-size: .87rem; font-weight: 500;
  box-shadow: var(--shadow-lg);
  display: flex; align-items: center; gap: 10px;
  max-width: 320px;
  animation: toast-in .3s cubic-bezier(.4,0,.2,1) forwards;
}
.toast.removing { animation: toast-out .3s cubic-bezier(.4,0,.2,1) forwards; }
.toast-icon { font-size: 1.1rem; }
@keyframes toast-in  { from { opacity:0; transform: translateX(20px); } to { opacity:1; transform: none; } }
@keyframes toast-out { from { opacity:1; transform: none; } to { opacity:0; transform: translateX(20px); } }

/* ─── RESPONSIVE ───────────────────────────────────────────────────────────── */
@media (max-width: 1100px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-grid .featured-article { grid-column: span 2; }
}

@media (max-width: 900px) {
  .hero { grid-template-columns: 1fr; }
  .hero-visual { min-height: 340px; }
  .deals-inner { grid-template-columns: 1fr; }
  .cat-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 720px) {
  .header-inner { grid-template-columns: auto 1fr auto; }
  .main-nav { display: none; }
